// Prepara el aviso del banco: junta asunto y cuerpo, quita el texto citado
// y el pie automatico del banco, y decide si es un aviso de pago o publicidad.
const item = $input.first().json ?? {};

const cuerpoBruto = item.body !== undefined ? item.body : (item.text ?? item.html ?? item.contenido ?? '');
const cuerpo = typeof cuerpoBruto === 'string'
  ? cuerpoBruto
  : String(cuerpoBruto.texto ?? cuerpoBruto.cuerpo ?? cuerpoBruto.contenido ?? '');
const asunto = String(
  item.asunto ?? item.subject ??
  (cuerpoBruto && typeof cuerpoBruto === 'object' ? (cuerpoBruto.asunto ?? cuerpoBruto.subject ?? '') : '') ?? ''
);

// Quita las lineas citadas (empiezan por >) y el pie del banco.
const texto = [asunto, cuerpo]
  .join('\n')
  .split('\n')
  .filter((linea) => !/^\s*>/.test(linea))
  .filter((linea) => !/^Banco Ejemplo\s*$/.test(linea))
  .filter((linea) => !/mensaje se ha generado autom/i.test(linea))
  .filter((linea) => !/por favor, no responda/i.test(linea))
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const minus = texto.toLowerCase();
const esPublicidad = /(ofertas|domicilias|domiciliar|descuento|condiciones de tu oficina|150\s*€)/.test(minus);
const tieneMarcasDePago = /(bizum|transferencia|ingreso|abono en cuenta|pago recibido)/.test(minus);
const tieneDatos = /(importe|ordenante|concepto)/.test(minus);
const es_aviso_de_pago = !esPublicidad && tieneMarcasDePago && tieneDatos;

const canal = /transferencia/i.test(minus) ? 'transferencia' : 'bizum';

return [{ json: { texto, asunto, es_aviso_de_pago, canal } }];

// Lee lo que devuelve el modelo y lo normaliza.
// Si el modelo no esta disponible o no devuelve un JSON utilizable, entra el extractor
// determinista por expresiones regulares: el flujo no se queda nunca sin datos.
const entrada = $input.first().json ?? {};
const textoOriginal = $('Normalizar correo').first().json?.texto ?? '';

// Convierte '10,00' / '1.842,30' / '10.00' en numero.
const aNumero = (bruto) => {
  if (bruto === null || bruto === undefined) return null;
  let s = String(bruto).trim().replace(/\s/g, '').replace(/[^0-9.,]/g, '');
  if (!s) return null;
  const coma = s.lastIndexOf(',');
  const punto = s.lastIndexOf('.');
  if (coma >= 0 && punto >= 0) {
    s = coma > punto ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (coma >= 0) {
    s = s.replace(',', '.');
  } else if (punto >= 0) {
    const decimales = s.length - punto - 1;
    if (decimales === 3 && s.split('.').length > 2) s = s.replace(/\./g, '');
  }
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

// Extractor determinista: mismo contrato que el modelo, pero sin modelo.
const extraerPorRegex = (texto) => {
  const t = String(texto ?? '');
  // Ojo: [ \t] en vez de \s, para no leer la linea siguiente cuando el campo va vacio
  // (por ejemplo 'Concepto:' sin nada despues).
  const mImporte = t.match(/importe[ \t]*[:.]*[ \t]*([0-9][0-9.,]*)[ \t]*(?:eur|€)/i)
    || t.match(/bizum de[ \t]*([0-9][0-9.,]*)[ \t]*€/i)
    || t.match(/([0-9][0-9.,]*)[ \t]*(?:eur|€)/i);
  const mOrdenante = t.match(/ordenante[ \t]*[:.]+[ \t]*(.+)/i);
  const mConcepto = t.match(/concepto[ \t]*[:.]+[ \t]*(.+)/i);
  return {
    ordenante: mOrdenante ? mOrdenante[1].trim() : '',
    importe: mImporte ? aNumero(mImporte[1]) : null,
    concepto: mConcepto ? mConcepto[1].trim() : '',
  };
};

let datos = null;
let origen = 'regex';
const respuesta = String(entrada.text ?? entrada.output ?? entrada.response ?? '');
const limpio = respuesta.replace(/```json/gi, '').replace(/```/g, '').trim();
const inicio = limpio.indexOf('{');
const fin = limpio.lastIndexOf('}');
if (inicio >= 0 && fin > inicio) {
  try {
    const parseado = JSON.parse(limpio.slice(inicio, fin + 1));
    if (parseado && typeof parseado === 'object') {
      datos = parseado;
      origen = 'modelo';
    }
  } catch (e) {
    datos = null;
  }
}

if (!datos) datos = extraerPorRegex(textoOriginal);

const importe = aNumero(datos.importe);
const ordenante = String(datos.ordenante ?? '').trim();
const concepto = String(datos.concepto ?? '').trim();

if (!ordenante || !importe || importe <= 0) {
  // Ni el modelo ni el regex han sido capaces: no se inventa nada, se avisa a Marisa.
  return [{ json: { ordenante, importe, concepto, origen, no_se_puede_interpretar: true, texto: textoOriginal } }];
}

return [{ json: { ordenante, importe, concepto, origen, no_se_puede_interpretar: false, texto: textoOriginal } }];

// Decide que hacer con el pago, con los datos de la API (reglas A2 y A3).
//
// - Si hay dudas (cliente desconocido, apartado ambiguo, sin concepto) -> NO se registra nada.
// - Si paga de mas o el apartado esta fuera de plazo -> NO se registra nada, se avisa a Marisa.
// - Si todo cuadra -> se registra el abono.
const r = $input.first().json ?? {};
const apartado = r.apartado ?? null;
const importe = Number(r.importe ?? 0);

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());

let accion = 'avisar';
let motivo = r.motivo ?? 'error_tecnico';
let detalle = r.detalle ?? '';

if (motivo === 'registrar' && apartado) {
  if (!importe || importe <= 0) {
    motivo = 'error_tecnico';
    detalle = 'El importe del aviso no es valido';
  } else if (String(apartado.estado) !== 'activo') {
    motivo = 'fuera_de_plazo';
    detalle = 'El apartado #' + apartado.id + ' esta ' + apartado.estado + ' y no admite abonos';
  } else if (apartado.fecha_limite && String(apartado.fecha_limite) < hoy) {
    motivo = 'fuera_de_plazo';
    detalle = 'El apartado #' + apartado.id + ' vencia el ' + apartado.fecha_limite;
  } else if (importe > Number(apartado.pendiente) + 0.001) {
    motivo = 'importe_excede';
    detalle = 'Paga ' + euros(importe) + ' pero solo quedaban ' + euros(apartado.pendiente) + ' pendientes';
  } else {
    accion = 'registrar';
    detalle = 'Abono de ' + euros(importe) + ' para el apartado #' + apartado.id;
  }
}

return [{
  json: {
    accion,
    motivo,
    detalle,
    importe,
    apartado,
    ordenante: r.ordenante ?? '',
    concepto: r.concepto ?? '',
    canal: $('Normalizar correo').first().json?.canal ?? 'bizum',
  },
}];

// Comprueba lo que ha devuelto la API. Si no ha ido bien, se avisa a Marisa
// con el motivo que dice la propia app (nunca se inventa el motivo).
const r = $input.first().json ?? {};
const ok = r.id !== undefined && r.estado !== undefined;
const motivoApi = r.detail ?? r.message ?? (r.error ? String(r.error) : 'La API no ha devuelto el apartado');

return [{
  json: {
    registrado: ok,
    motivo: ok ? 'registrado' : 'error_tecnico',
    detalle: ok ? 'Abono de ' + Number($('Decidir').first().json?.importe ?? 0).toFixed(2) + ' EUR registrado en el apartado #' + r.id : String(motivoApi),
    apartado: ok ? r : null,
    pendiente: ok ? r.pendiente : null,
    estado: ok ? r.estado : null,
  },
}];

// Mensaje para Marisa cuando NO se ha registrado el abono (reglas A2 y A3).
// No se registra nada: solo se pregunta y se explica el motivo.
const d = $input.first().json ?? {};
const decision = $('Decidir').first().json ?? {};
// 'tienda' quiere decir 'la direccion de la tienda', que resuelve el
// subflujo de notificacion con el fichero de configuracion.
const emailTienda = 'tienda';
const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const MOTIVOS = {
  importe_excede: 'el importe supera lo que queda pendiente',
  fuera_de_plazo: 'el apartado esta fuera de plazo',
  apartado_ambiguo: 'hay varios apartados que pueden ser',
  cliente_desconocido: 'no coincide con ningun cliente',
  sin_concepto: 'no se sabe con certeza de quien es',
  error_tecnico: 'ha habido un problema tecnico',
};

const motivo = d.motivo ?? decision.motivo ?? 'error_tecnico';
const detalle = d.detalle ?? decision.detalle ?? '';
const importe = decision.importe ?? d.importe ?? 0;
const apartado = decision.apartado ?? null;

const cuerpo = [
  'Hay un pago que no he registrado. Necesito que me digas a que apartado va:',
  '',
  'Motivo: ' + (MOTIVOS[motivo] ?? motivo),
  'Ordenante: ' + (decision.ordenante ?? '(desconocido)'),
  'Importe: ' + euros(importe),
  'Concepto: ' + (decision.concepto || '(vacio)'),
  'Canal: ' + (decision.canal ?? 'bizum'),
  'Detalle: ' + (detalle || '-'),
  apartado ? 'Apartado candidato: #' + apartado.id + ' ' + apartado.cliente + ' (pendiente ' + euros(apartado.pendiente) + ')' : 'Apartado candidato: ninguno',
  '',
  'No he registrado nada: espero tu confirmacion.',
].join('\n');

return [{ json: { canal: 'email', email: emailTienda, asunto: 'Pago sin registrar · ' + (MOTIVOS[motivo] ?? motivo), cuerpo, cuerpo_html: '<p>' + escapar(cuerpo).replace(/\n/g, '<br>') + '</p>' } }];
